  "sql": "WITH __slayer_stage_em AS (\n  SELECT\n    _stage_inner.\"campaign_members.customer_id\" AS \"customer_id\",\n    _stage_inner.\"campaign_members.n\" AS \"n\"\n  FROM (\n    SELECT\n      campaign_members.customer_id AS \"campaign_members.customer_id\",\n      COUNT(*) AS \"campaign_members.n\"\n    FROM campaign_members AS campaign_members\n    LEFT JOIN campaigns AS campaigns\n      ON campaign_members.campaign_id = campaigns.id\n    WHERE\n      campaigns.channel = 'email'\n    GROUP BY\n      campaign_members.customer_id\n  ) AS _stage_inner\n)\nSELECT\n  customers__regions.name AS \"orders.customers.regions.name\",\n  CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\nFROM orders AS orders\nLEFT JOIN customers AS customers\n  ON orders.customer_id = customers.id\nLEFT JOIN regions AS customers__regions\n  ON customers.region_id = customers__regions.id\nINNER JOIN __slayer_stage_em AS em\n  ON orders.customer_id = em.customer_id\nWHERE\n  em.n > 0\nGROUP BY\n  customers__regions.name\nORDER BY\n  \"orders.customers.regions.name\" ASC\nLIMIT 101"
}
